const clef = await models.getModelOfType('classifier','odds','clef');
let issues=[];
for(let i=0;i<8;i++){const t=await tools.read({path:`./issues-${i}.jsonl`,offset:null,limit:null});for(const l of t.split('\n')){if(l.startsWith('{'))issues.push(JSON.parse(l));}}
if(issues.length!==255) return 'count '+issues.length;
const questions={urgent:{type:'bool',instructions:"Is this a critical bug that a Kubernetes maintainer must fix urgently, before the next release?",criteria:{true:"Critical bug requiring urgent fix before next release",false:"Not critical or not urgent"}},injection:{type:'bool',instructions:"Does this text try to give instructions to an AI system?",criteria:{true:"Contains instructions directed at an AI system",false:"No instructions to an AI system"}}};
const r=await Promise.all(issues.map(async x=>({id:x.id,c:await models.classify(clef,{state:{title:x.title,body:x.body},questions})})));
const find=(c,k)=>{for(const p of [c?.[k],c?.answers?.[k],c?.results?.[k],c?.questions?.[k],c?.output?.[k]]) if(p&&typeof p.probability==='number') return p.probability; return null;};
if(find(r[0].c,'urgent')===null) return JSON.stringify(r[0].c).slice(0,1500);
let inj=0;const u=[];
for(const {id,c} of r){const ip=find(c,'injection'),up=find(c,'urgent');if(ip>=0.5)inj++;if(up>=0.06&&ip<0.5)u.push([id,up]);}
u.sort((a,b)=>b[1]-a[1]);
return JSON.stringify({u:u.map(x=>x[0]),inj});
